const CACHE="prisma-fw-react-v1";self.addEventListener("install",event=>{event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(["/","/manifest.webmanifest","/icon.svg"])))});self.addEventListener("activate",event=>{event.waitUntil((async()=>{for(const key of await caches.keys())if(key.startsWith("prisma-fw-react-")&&key!==CACHE)await caches.delete(key);await self.clients.claim()})())});self.addEventListener("fetch",event=>{const req=event.request,url=new URL(req.url);if(req.method!=="GET"||url.origin!==self.location.origin)return;if(req.mode==="navigate"){event.respondWith(fetch(req).then(response=>{if(response.ok)caches.open(CACHE).then(c=>c.put("/",response.clone()));return response}).catch(async()=>await caches.match("/")||Response.error()));return}event.respondWith((async()=>{const cached=await caches.match(req);if(cached)return cached;const response=await fetch(req);if(response.ok)await(await caches.open(CACHE)).put(req,response.clone());return response})())});